"""Download WhatsApp voice notes and photos through the Graph API.

Example:
    out = download_media("2708226019592949", token, Path("media"))
    dest = out["path"]
    size = out["bytes"]
"""
import base64
import hashlib
import hmac
from pathlib import Path

import requests

MAX_BYTES = 16 * 1024 * 1024

EXTENSIONS = {
    "audio/ogg": ".ogg",
    "audio/mpeg": ".mp3",
    "audio/mp4": ".m4a",
    "audio/aac": ".aac",
    "audio/amr": ".amr",
    "image/jpeg": ".jpg",
    "image/png": ".png",
}


class MediaError(Exception):
    """Raised for invalid ids, bad metadata, or failed downloads."""


def _valid_id(media_id: str) -> bool:
    return (
        isinstance(media_id, str)
        and len(media_id) > 0
        and media_id.isascii()
        and media_id.isdigit()
    )


def verify_sha256(data: bytes, expected: str) -> bool:
    """Return True when expected matches the SHA-256 of data."""
    if not isinstance(data, (bytes, bytearray)):
        return False
    if not isinstance(expected, str):
        return False
    if len(expected) == 64:
        actual = hashlib.sha256(data).hexdigest()
        return hmac.compare_digest(actual.lower(), expected.lower())
    if len(expected) == 44:
        digest = hashlib.sha256(data).digest()
        actual = base64.b64encode(digest).decode("ascii")
        return hmac.compare_digest(actual, expected)
    return False


def media_path(media_dir: Path, media_id: str, mime_type: str) -> Path:
    """Return media_dir / (media_id + extension for mime_type)."""
    if not _valid_id(media_id):
        raise MediaError("invalid media id")
    base = str(mime_type).split(";")[0].strip().lower()
    ext = EXTENSIONS.get(base)
    if ext is None:
        raise MediaError("unsupported media type")
    return Path(media_dir) / (media_id + ext)


def _get(session, url: str, token: str):
    try:
        return session.get(
            url, headers={"Authorization": f"Bearer {token}"}, timeout=30
        )
    except requests.RequestException:
        raise MediaError("request failed") from None


def _get_meta(session, url: str, token: str) -> dict:
    resp = _get(session, url, token)
    if resp.status_code != 200:
        raise MediaError(f"metadata request failed with status {resp.status_code}")
    return resp.json()


def download_media(
    media_id: str,
    token: str,
    media_dir: Path,
    expected_sha256: str | None = None,
    session=None,
    graph_url: str = "https://graph.facebook.com",
) -> dict:
    """Fetch metadata, then bytes, verify, and store the file."""
    if not _valid_id(media_id):
        raise MediaError("invalid media id")
    if session is None:
        session = requests.Session()
    meta = _get_meta(session, graph_url.rstrip("/") + "/" + media_id, token)
    path = media_path(media_dir, media_id, meta["mime_type"])
    if path.is_file() and verify_sha256(path.read_bytes(), meta["sha256"]):
        data = path.read_bytes()
        return {
            "path": path,
            "mime_type": meta["mime_type"],
            "bytes": len(data),
            "sha256": hashlib.sha256(data).hexdigest(),
            "cached": True,
        }
    resp = _get(session, meta["url"], token)
    if resp.status_code == 404:
        meta = _get_meta(session, graph_url.rstrip("/") + "/" + media_id, token)
        path = media_path(media_dir, media_id, meta["mime_type"])
        resp = _get(session, meta["url"], token)
        if resp.status_code != 200:
            raise MediaError(f"download failed with status {resp.status_code}")
    elif resp.status_code != 200:
        raise MediaError(f"download failed with status {resp.status_code}")
    body = resp.content
    if len(body) > MAX_BYTES:
        raise MediaError("file exceeds size limit")
    if len(body) != meta["file_size"]:
        raise MediaError("file size mismatch")
    if not verify_sha256(body, meta["sha256"]):
        raise MediaError("checksum mismatch")
    if expected_sha256 is not None and not verify_sha256(body, expected_sha256):
        raise MediaError("checksum mismatch")
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + ".part")
    tmp.write_bytes(body)
    tmp.replace(path)
    return {
        "path": path,
        "mime_type": meta["mime_type"],
        "bytes": len(body),
        "sha256": hashlib.sha256(body).hexdigest(),
        "cached": False,
    }
```
- Single request helper plus metadata helper keeps download_media straight line.
- Cache checked once before any byte download, never duplicated in refresh branch.
- Only requests.RequestException is caught, re-raised from None with safe text.
- Usage example avoids print, source stays short with no banned strings.
